const body = $input.item.json.body || $input.item.json || {};
const userMessage = body.message || body.text || '';
const conversationId = body.conversation_id || 'default';
const userId = body.user_id || 'user';
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const systemPrompt = `You are HomeBot (Private Desktop AI Assistant), a helpful desktop AI assistant. Today is ${today}. Be concise, accurate, and use markdown formatting.`;

const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: userMessage }
];

return {
  json: {
    model: 'qwen2.5:7b',
    messages: messages,
    stream: false,
    user_message: userMessage,
    conversation_id: conversationId,
    user_id: userId
  }
};

const ollamaRes = $input.item.json;
const content = ollamaRes.message?.content || ollamaRes.response || 'No response';
return {
  json: {
    output: content,
    data: {
      assistant: {
        role: 'assistant',
        content: content
      }
    }
  }
};

const secret = process.env.HOMEBOT_WEBHOOK_SECRET;
if (secret) {
  const hdrs = $input.first()?.json?.headers || {};
  const incoming = hdrs['x-homebot-auth'] || hdrs['X-HOMEBOT-Auth'] || '';
  if (incoming !== secret) {
    throw new Error('Unauthorized: invalid or missing X-HOMEBOT-Auth header');
  }
}
return $input.all();
